"use client";
import React from "react";
import Destinations from "../../after-your-booking/destinations";
import BlogTeasers from "../../after-your-booking/blog-teasers";

type Tip = { title: string; image: string; body: string };

const planning: Tip[] = [
  {
    title: "Select a sustainable provider",
    image: "/images/africaanimals.jpg",
    body: "Travel with companies that align with your environmental values, actively working to promote sustainability and lessen their carbon impact. At TravelShop Booking, our Climate Action Plan ensures all operators will have sustainability policies by 2030. Discover a responsible operator now.",
  },
  {
    title: "Minimize air travel whenever feasible",
    image: "/images/plane.webp",
    body: "Opt for trains or buses to avoid air travel and enjoy a more eco-friendly journey. If flying is necessary, prioritize direct flights and choose airlines that use sustainable aviation fuel. Extending your stay can help maximize the benefits to local communities.",
  },
  {
    title: "Minimize your environmental impact",
    image: "/images/carbon.jpg",
    body: "Think about counteracting your CO2 emissions through the purchase of carbon credits or contributions to environmental groups. By taking ownership of your carbon footprint and supporting projects dedicated to a sustainable future, you help make a meaningful difference.",
  },
];

const preparing: Tip[] = [
  {
    title: "Traveling with minimal luggage",
    image: "/images/packing.webp",
    body: "Packing light not only enhances your comfort but also helps lower your carbon footprint. By carrying less, you lighten the load for your mode of transport, leading to reduced fuel usage and fewer emissions — contributing to a healthier environment.",
  },
  {
    title: "Minimize waste and embrace recycling",
    image: "/images/recycle.jpg",
    body: "By carrying a reusable water bottle, avoiding single-use plastics, and recycling whenever possible, you make a significant contribution to reducing your environmental impact — helping protect our oceans, wildlife, and natural resources.",
  },
  {
    title: "Opt for biodegradable alternatives",
    image: "/images/product.webp",
    body: "Waste disposal systems may not be efficient everywhere. For items that can't be recycled, choose products that are free from harmful chemicals and come in recycled or recyclable materials, so even when waste is produced, its impact is minimized.",
  },
];

const TipCard = ({ tip }: { tip: Tip }) => (
  <div className="tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-shadow-lg tw-transition-shadow tw-duration-200">
    <img
      src={tip.image}
      alt={tip.title}
      loading="lazy"
      className="tw-h-48 tw-w-full tw-object-cover"
    />
    <div className="tw-flex tw-flex-col tw-flex-1 tw-p-6">
      <h3 className="tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-m-0">
        {tip.title}
      </h3>
      <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
        {tip.body}
      </p>
    </div>
  </div>
);

const PositiveImpact = () => {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/naturebanner1.jpg')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.8) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Positive Impact
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Green Living Hacks
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Practical tips and strategies to help minimize your carbon
              footprint and make your travel more sustainable.
            </p>
          </div>
        </div>
      </section>

      {/* Intro */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-text-center">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Strategies for Minimizing Your Footprint
          </h2>
          <p className="tw-mt-5 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            As part of our Climate Action Plan, we are dedicated to fostering a
            culture of green travel among our employees, travelers, operators,
            agents, and industry partners. Every trip affects both the
            environment and local communities, which is why we&apos;ve curated a
            list of practical tips and strategies to help minimize your carbon
            footprint and make your travel more sustainable.
          </p>
        </div>
      </section>

      {/* When planning your journey */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(22px,2.8vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              When planning your journey
            </h2>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {planning.map((tip) => (
              <TipCard key={tip.title} tip={tip} />
            ))}
          </div>
        </div>
      </section>

      {/* When preparing for your trip */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(22px,2.8vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              When preparing for your trip
            </h2>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {preparing.map((tip) => (
              <TipCard key={tip.title} tip={tip} />
            ))}
          </div>
        </div>
      </section>

      <BlogTeasers />

      <Destinations />
    </main>
  );
};

export default PositiveImpact;
